// Generated by scripts/generate-openui-prompt.ts with npm run prompt. Do not edit by hand.
export const OPENUI_PROMPT = `Use show_ui with the openui field when you want to show a card, a summary, a table or a chart in the chat.
The OpenUI text must contain a root = Col([...]) line; every other line defines a component used by root.
Write all visible text in the language the user is writing in. Use full sentences, no bold, no asterisks and no dashes as connectors.
Show a single show_ui block per answer unless the user explicitly asks for more.
In buttons use @ToAssistant("text") to send the user's choice back to the agent.
Do not leave undefined references: every name you use must have a definition line.
The OpenUI text is limited to 20000 characters; the spec field stays available for the classic format.

## Syntax Rules

1. Each statement is on its own line: \`identifier = Expression\`
2. \`root\` is the entry point — every program must define \`root = Root(...)\`
3. Expressions are: strings ("..."), numbers, booleans (true/false), null, arrays ([...]), objects ({...}), or component calls TypeName(arg1, arg2, ...)
4. Use references for readability: define \`name = ...\` on one line, then use \`name\` later
5. EVERY variable (except root) MUST be referenced by at least one other variable. Unreferenced variables are silently dropped and will NOT render. Always include defined variables in their parent's children/items array.
6. Arguments are POSITIONAL (order matters, not names). Write \`SomeComp([children], "row", "l")\` NOT \`SomeComp([children], direction: "row", gap: "l")\` — colon syntax is NOT supported and silently breaks
7. Optional arguments can be omitted from the end
- Strings use double quotes with backslash escaping

## Component Signatures

Arguments marked with ? are optional. Sub-components can be inline or referenced; prefer references for better streaming.
Props marked \`$binding<type>\` accept a \`$variable\` reference for two-way binding.

Col(children: any[], gap?: number, align?: "start" | "center" | "end" | "stretch") — Vertical column. Without gap, blocks are spaced like an article.
Row(children: any[], gap?: number, align?: "start" | "center" | "end" | "stretch", justify?: "start" | "center" | "end" | "between", wrap?: boolean) — Horizontal row; items are vertically centered.
Card(children: any[], variant?: "outline" | "soft", padding?: number, gap?: number) — Panel with a border. soft is a filled panel for summaries.
Title(text: string, size?: "sm" | "md" | "lg" | "xl" | "2xl" | "3xl", color?: string) — Title. lg for a card title, 2xl for a large number.
Text(text: string | any[], size?: "xs" | "sm" | "md" | "lg", color?: string, weight?: "normal" | "medium" | "semibold", italic?: boolean, lineThrough?: boolean, tabularNums?: boolean, maxLines?: number) — Paragraph. Supports plain text or a list of strings and inline components.
Caption(text: string, color?: string) — Small secondary text.
Badge(text: string, color?: "neutral" | "info" | "success" | "warning" | "danger" | "purple" | "pink") — Short colored label.
Button(label: string, action?: any, variant?: "solid" | "outline" | "soft" | "ghost", color?: "primary" | "danger" | "success", size?: "sm" | "md" | "lg", icon?: string, disabled?: boolean, block?: boolean) — Button. The action can be @ToAssistant, @OpenUrl, @Set, @Reset or @CopyToClipboard.
AgentLink(label: string, agentId: string, variant?: "solid" | "outline" | "soft" | "ghost", icon?: string) — Button that opens the chat of another Paseo agent (agentId returned by create_agent or list_agents). It sends no message to the agent, it only navigates.
Table(columns: string[], rows: any[][]) — Table. Each row lists its cells in column order.
Chart(type: "bar" | "line" | "area" | "pie" | "donut" | "scatter", data: Record<string, string | number>[], x?: string, series?: string[], format?: "number" | "currency" | "percent", currency?: string, stacked?: boolean, height?: number) — Chart over data rows. The plugin draws bar and line.
Divider() — Thin horizontal dividing line.
Spacer() — Fills the free space in a Row.
Grid(children: any[], columns?: number, minChildWidth?: number, gap?: number) — Grid with equal columns (default 2). With minChildWidth the columns stack on narrow screens.
Carousel(children: any[], gap?: number, itemWidth?: number) — Horizontal scrolling row of cards with snap. Ideal on phones for places, products or options: one Card per item.
List(items: any[], marker?: "bullet" | "number" | "none", timeline?: boolean) — Bulleted or numbered list. With timeline the items are joined by a line. Items are strings or ListItem.
ListItem(title: string, description?: string, marker?: string, children?: any[]) — List item with a title, optional description and marker (for example a time).
Image(src: string, alt: string, aspectRatio?: number, radius?: string | number, fit?: "cover" | "contain") — Photo from an http(s) URL or from a file on the Mac (absolute path or file://, embedded by the plugin). aspectRatio is width over height, for example 1.5.
SearchImage(query: string, fallback?: string, aspectRatio?: number, radius?: string | number, fit?: "cover" | "contain") — Photo found automatically on Wikipedia and Commons for a search. query: 2-4 precise words, for example the exact name of a place, monument, dish or product. fallback: 1-2 generic words about the kind of thing (for example pastries, tiramisu, cathedral) used when the exact photo does not exist, as often happens for small places. If nothing is found it shows a placeholder.
Icon(name: string, size?: number) — Lucide icon by name in kebab-case (map-pin, star, clock, coffee, croissant, phone, globe, shopping-bag, heart, calendar). Use it next to a text, in a Row.
Link(text: string, url: string) — Clickable link that opens an http(s) URL.
Quote(text: string, cite?: string) — Quote with a side rule. cite gives the source.
Code(code: string, language?: string) — Monospaced code block, with horizontal scrolling.
Label(text: string) — Field or group label.
Input(value: $binding<string | number>, label?: string, type?: "text" | "number", placeholder?: string) — Text or number field. value is a $ variable that other elements read; a number field stores numbers.
TextArea(value: $binding<string>, label?: string, placeholder?: string, rows?: number) — Multi-line text area bound to a $ variable.
Select(value: $binding<string>, options: any[], label?: string, placeholder?: string) — Dropdown menu for long option lists. Options are strings or {value, label}.
SegmentedControl(value: $binding<string>, options: any[], block?: boolean) — Two or four short choices side by side. Options are strings or {value, label}.
Slider(value: $binding<number>, min: number, max: number, step?: number, label?: string, unit?: string, marks?: {value: number, label: string}[]) — Numeric value between min and max, with label and unit (% or $). Adjusted with the −/+ steps.
Checkbox(checked: $binding<boolean>, label: string, lineThrough?: boolean) — Checkbox bound to a boolean $ variable. lineThrough strikes through the label when checked.

## Hoisting & Streaming (CRITICAL)

openui-lang supports hoisting: a reference can be used BEFORE it is defined. The parser resolves all references after the full input is parsed.

During streaming, the output is re-parsed on every chunk. Undefined references are temporarily unresolved and appear once their definitions stream in. This creates a progressive top-down reveal — structure first, then data fills in.

**Recommended statement order for optimal streaming:**
1. \`root = Root(...)\` — UI shell appears immediately
2. Component definitions — fill in as they stream
3. Data values — leaf content last

Always write the root = Root(...) statement first so the UI shell appears immediately, even before child data has streamed in.
## Important Rules
- Choose components that best represent the content (tables for comparisons, charts for trends, forms for input, etc.)

## Final Verification
Before finishing, walk your output and verify:
1. root = Root(...) is the FIRST line (for optimal streaming).
2. Every referenced name is defined. Every defined name (other than root) is reachable from root.

- STYLE: the block is visual, airy and box-free. Do not wrap everything in a Card and do not nest Cards: use one Card per list item, never around the whole block. The rest goes directly in Col with Title, Text, images and icons.
- PHOTOS: for places, landmarks, venues, dishes, products and well-known people always add a SearchImage (a query of 2 to 4 precise words, for example the exact name of the place and the city; as the second argument a fallback of 1 or 2 generic words about the kind of thing, for example SearchImage("Pasticceria Biasetto Padova", "pastries"), because small venues have no precise photo and without a fallback an empty box remains) at the top of the card or in a row of three photos with Carousel. A Row of three SearchImage with aspectRatio 1 works well as an opening strip.
- LOCAL IMAGES: to show a screenshot or a file that lives on the computer running the daemon, pass Image the absolute path or a file:// address (for example Image("/Users/.../screenshot.jpg", "Description")): the plugin shrinks it and embeds it in the block, so it is visible from the phone too. This works on macOS; elsewhere use an image URL. If the file does not exist show_ui answers with an error: fix the path, do not fall back to a placeholder.
- ICONS: next to every short data point put a Lucide Icon in a Row (map-pin for the address, star for the rating, clock for opening hours, phone, globe, euro, coffee), and pass icon to Buttons (map, external-link, send, check). No emoji instead of icons.
- Lists of venues, places, products, offers or options do NOT go in a Table: use a Carousel (or a Grid) with one Card per item. Inside the card: SearchImage at the top, Title for the name, Badge for category or rating, Icon + Caption rows for address and hours, Text for a short note, a soft Button with icon to open the map or the site (or Link).
- OTHER AGENTS' CHATS: when you talk about a Paseo agent you created or that already exists (create_agent, list_agents), put AgentLink("Open chat", "<agentId>") next to its name or status, where agentId is the exact id of the agent: it opens its chat without sending anything. Only for Paseo agents that have an id, not for internal subagents (Task) that have no chat. For several agents use one Card per agent with a Text saying what it is doing and an AgentLink.
- Table only for comparisons of numbers or short values with at most three columns; on a phone every row becomes a block, so no long sentences in cells.
- Chart for trends and numeric comparisons, Title 2xl with Caption for a key number, List with timeline for sequences and schedules, Button with @ToAssistant to let the user pick the next step.
- TITLE: the title parameter of show_ui already appears as the block heading, so do NOT repeat it with a Title inside the OpenUI (it would appear twice): use title or a Title in the content, never both. Open with a line of Text saying what the block shows; no more than six cards per carousel without a reason.`;
